return {
    ["1:1高精复刻贝克兰德博物馆同款，据说坐在上面阅读大帝日记更易破译。"] = "A 1:1 high-precision replica of the same model from the Backlund Museum. It is said that sitting on it while reading the Emperor's diary makes it easier to decipher.",
