    ["弗兰克"] = "Откровенный",
    ["弗莱"] = "",
    ["弧线勾勒着光线的轨迹，使空间明亮而富有层次。"] = "Дуга очерчивает траекторию света, делая пространство ярким и многослойным.",
    ["当前%s数量不足，无法摆放"] = "Недостаточно предметов «%s», невозможно разместить",
    ["当煤气路灯的光芒穿透雨水照耀车身，每个人都将从此处领略到金属的美感。"] = "Когда свет газового фонаря пробивается сквозь дождь и светит на кузов кареты, от этого каждый оценит красоту металла.",
    ["微光烛台"] = "Мерцающий подсвечник",
    ["成对的壁灯，光影在墙面上交叠。"] = "Парные бра, с перекрытием света и тени на стене.",
    ["成片的紫色花穗向风中倾斜，香气会顺着木栅一路漫到院门口。"] = "Пышные пурпурные соцветия склоняются на ветру, и аромат струится вдоль деревянного забора к самым воротам двора.",
    ["战马"] = "Боевой конь",
    ["戴莉"] = "Дейли",
    ["打过蜡的木架结实而富有光泽，瓶身上的标签写着只有厨师本人能看懂的简笔。"] = "Вощеная деревянная полка прочная и блестящая, а этикетки на бутылках написаны стенографией, понятной только шеф-повару.",
    ["打造柜子的木材很是普通，但安放其中的书页图册增添了其价值。"] = "Древесина, из которой изготовлен шкаф, вполне обычная, но помещенные внутри книги и атласы добавляют ему ценности.",
    ["抛光的桃木与金线点缀，让整座架子更像一件奢华的家具。"] = "Полированное красное дерево и украшения с золотой нитью делают всю полку более похожей на предмет роскошной мебели.",
    ["抽屉内收纳着文件和手稿，里面的秘密或许比金银财宝更有价值。"] = "В ящиках хранятся документы и рукописи; тайны внутри могут быть более ценными, чем золото и серебро.",
    ["拱形的窗格嵌着幽光，透过它望见的，未必是现实的风景。"] = "The arched window pane is embedded with a dim light; what one sees through it may not necessarily be the scenery of reality.",
    ["拱形的绿门没有锁也没有钥匙，邀请与拒绝全凭主人指认。"] = "У арочных зеленых ворот нет ни замка, ни ключа; Приглашение и отклонение полностью зависят от назначения владельца.",
    ["拼合的皮革让踩上去的感受更加柔软，因此也更受小朋友的喜欢。"] = "Комбинированная кожа делает ощущение наступления на нее мягче, поэтому она больше нравится детям.",
    ["挂画·春夜之邀"] = "Подвесная картина - Приглашение весенней ночи",
